  "rejected — resubmit needed": { es: "rechazado — es necesario volver a enviar", zh: "已拒绝 — 需要重新提交", ja: "却下 — 再提出が必要", de: "abgelehnt — erneute Einreichung erforderlich", ru: "отклонено — требуется повторная отправка", it: "respinto — è necessario reinviare", fr: "rejeté — nouvelle soumission requise", pt: "rejeitado — é necessário reenviar", ko: "거부됨 — 재제출 필요", ar: "مرفوض — يلزم إعادة التقديم", hi: "अस्वीकृत — पुनः सबमिट करना आवश्यक" },
  "approved": { es: "aprobado", zh: "已批准", ja: "承認済み", de: "genehmigt", ru: "одобрено", it: "approvato", fr: "approuvé", pt: "aprovado", ko: "승인됨", ar: "موافَق عليه", hi: "स्वीकृत" },
  "Planned until": { es: "Previsto hasta", zh: "计划至", ja: "予定期限", de: "Geplant bis", ru: "Запланировано до", it: "Previsto fino al", fr: "Prévu jusqu'au", pt: "Planeado até", ko: "예정 기한", ar: "مُخطَّط حتى", hi: "नियोजित अवधि" },
