  "only": { es: "solo", zh: "仅", ja: "のみ", de: "nur", ru: "только", it: "solo", fr: "seulement", pt: "apenas", ko: "만", ar: "فقط", hi: "केवल" },
  "to the pledge address": { es: "a la dirección de compromiso", zh: "到质押地址", ja: "pledge アドレスへ", de: "an die Pledge-Adresse", ru: "на pledge-адрес", it: "all’indirizzo di pledge", fr: "vers l’adresse de pledge", pt: "para o endereço de pledge", ko: "pledge 주소로", ar: "إلى عنوان pledge", hi: "pledge पते पर" },
  "not found on-chain": { es: "no se encontró on-chain", zh: "在链上未找到", ja: "オンチェーンで見つかりません", de: "nicht on-chain gefunden", ru: "не найдено в сети (on-chain)", it: "non trovato on-chain", fr: "introuvable on-chain", pt: "não encontrado on-chain", ko: "온체인에서 찾을 수 없음", ar: "غير موجود على السلسلة (on-chain)", hi: "ऑन-चेन नहीं मिला" },
  "no tx hash submitted yet": { es: "aún no se ha enviado el hash de tx", zh: "尚未提交交易哈希", ja: "tx ハッシュはまだ送信されていません", de: "noch kein Tx-Hash übermittelt", ru: "хеш tx ещё не отправлен", it: "nessun hash di tx ancora inviato", fr: "aucun hash de tx encore soumis", pt: "nenhum hash de tx enviado ainda", ko: "아직 tx 해시가 제출되지 않음", ar: "لم يتم إرسال هاش tx بعد", hi: "अभी तक कोई tx हैश सबमिट नहीं हुआ" },
  "Feedback for the team (required to reject, optional to approve)": { es: "Comentarios para el equipo (obligatorio para rechazar, opcional para aprobar)", zh: "给团队的反馈（拒绝时必填，批准时可选）", ja: "チームへのフィードバック（却下には必須、承認には任意）", de: "Feedback für das Team (zum Ablehnen erforderlich, zum Genehmigen optional)", ru: "Отзыв для команды (обязателен для отклонения, не обязателен для одобрения)", it: "Feedback per il team (obbligatorio per rifiutare, facoltativo per approvare)", fr: "Commentaires pour l’équipe (requis pour rejeter, facultatif pour approuver)", pt: "Feedback para a equipe (obrigatório para rejeitar, opcional para aprovar)", ko: "팀에 대한 피드백 (거부 시 필수, 승인 시 선택)", ar: "ملاحظات للفريق (مطلوبة للرفض، اختيارية للموافقة)", hi: "टीम के लिए फ़ीडबैक (अस्वीकार करने के लिए आवश्यक, स्वीकृत करने के लिए वैकल्पिक)" },
  "Approve — pledge verified": { es: "Aprobar — compromiso verificado", zh: "批准 — 质押已验证", ja: "承認 — pledge を確認済み", de: "Genehmigen — Pledge verifiziert", ru: "Одобрить — pledge проверен", it: "Approva — pledge verificato", fr: "Approuver — pledge vérifié", pt: "Aprovar — pledge verificado", ko: "승인 — pledge 확인됨", ar: "موافقة — تم التحقق من pledge", hi: "स्वीकृत करें — pledge सत्यापित" },
  "Send message": { es: "Enviar mensaje", zh: "发送消息", ja: "メッセージを送信", de: "Nachricht senden", ru: "Отправить сообщение", it: "Invia messaggio", fr: "Envoyer le message", pt: "Enviar mensagem", ko: "메시지 보내기", ar: "إرسال الرسالة", hi: "संदेश भेजें" },
