  "POA deadline": { es: "Fecha límite de POA", zh: "POA 截止时间", ja: "POA 期限", de: "POA-Frist", ru: "Срок POA", it: "Scadenza POA", fr: "Échéance POA", pt: "Prazo do POA", ko: "POA 마감일", ar: "الموعد النهائي لـ POA", hi: "POA समय-सीमा" },
  "auto-extended": { es: "extendido automáticamente", zh: "已自动延长", ja: "自動延長済み", de: "automatisch verlängert", ru: "продлено автоматически", it: "esteso automaticamente", fr: "prolongé automatiquement", pt: "estendido automaticamente", ko: "자동 연장됨", ar: "مُمدَّد تلقائيًا", hi: "स्वतः बढ़ाया गया" },
  "board +": { es: "junta +", zh: "理事会 +", ja: "理事会 +", de: "Vorstand +", ru: "совет +", it: "consiglio +", fr: "conseil +", pt: "conselho +", ko: "이사회 +", ar: "المجلس +", hi: "बोर्ड +" },
  "One-time board extension (§11.5)": { es: "Prórroga única de la junta (§11.5)", zh: "理事会一次性延长（§11.5）", ja: "理事会による一度限りの延長（§11.5）", de: "Einmalige Vorstandsverlängerung (§11.5)", ru: "Однократное продление советом (§11.5)", it: "Proroga una tantum del consiglio (§11.5)", fr: "Prolongation unique du conseil (§11.5)", pt: "Prorrogação única do conselho (§11.5)", ko: "이사회의 1회 연장 (§11.5)", ar: "تمديد لمرة واحدة من المجلس (§11.5)", hi: "बोर्ड द्वारा एक-बार का विस्तार (§11.5)" },
  "Extend deadline": { es: "Ampliar el plazo", zh: "延长截止时间", ja: "期限を延長", de: "Frist verlängern", ru: "Продлить срок", it: "Estendi la scadenza", fr: "Prolonger l'échéance", pt: "Estender o prazo", ko: "마감일 연장", ar: "تمديد الموعد النهائي", hi: "समय-सीमा बढ़ाएँ" },
  "Reply…": { es: "Responder…", zh: "回复…", ja: "返信…", de: "Antworten…", ru: "Ответить…", it: "Rispondi…", fr: "Répondre…", pt: "Responder…", ko: "답글…", ar: "رد…", hi: "जवाब दें…" },
  "Send reply": { es: "Enviar respuesta", zh: "发送回复", ja: "返信を送信", de: "Antwort senden", ru: "Отправить ответ", it: "Invia risposta", fr: "Envoyer la réponse", pt: "Enviar resposta", ko: "답글 보내기", ar: "إرسال الرد", hi: "जवाब भेजें" },
  "Delete comment?": { es: "¿Eliminar comentario?", zh: "删除评论？", ja: "コメントを削除しますか？", de: "Kommentar löschen?", ru: "Удалить комментарий?", it: "Eliminare il commento?", fr: "Supprimer le commentaire ?", pt: "Excluir comentário?", ko: "댓글을 삭제하시겠습니까?", ar: "حذف التعليق؟", hi: "टिप्पणी हटाएं?" },
