  "Month": { es: "Mes", zh: "月", ja: "月", de: "Monat", ru: "Месяц", it: "Mese", fr: "Mois", pt: "Mês", ko: "월", ar: "الشهر", hi: "महीना" },
  "Day": { es: "Día", zh: "日", ja: "日", de: "Tag", ru: "День", it: "Giorno", fr: "Jour", pt: "Dia", ko: "일", ar: "اليوم", hi: "दिन" },
