  "all rounds": { es: "todas las rondas", zh: "所有轮次", ja: "すべてのラウンド", de: "alle Runden", ru: "все раунды", it: "tutti i round", fr: "tous les tours", pt: "todas as rodadas", ko: "모든 라운드", ar: "كل الجولات", hi: "सभी राउंड" },
  "Funding rounds (§5/§6)": { es: "Rondas de financiación (§5/§6)", zh: "资助轮次 (§5/§6)", ja: "資金提供ラウンド (§5/§6)", de: "Förderrunden (§5/§6)", ru: "Раунды финансирования (§5/§6)", it: "Round di finanziamento (§5/§6)", fr: "Tours de financement (§5/§6)", pt: "Rodadas de financiamento (§5/§6)", ko: "펀딩 라운드 (§5/§6)", ar: "جولات التمويل (§5/§6)", hi: "फंडिंग राउंड (§5/§6)" },
