  "categories": { es: "categorías", zh: "类别", ja: "カテゴリ", de: "Kategorien", ru: "категории", it: "categorie", fr: "catégories", pt: "categorias", ko: "카테고리", ar: "الفئات", hi: "श्रेणियाँ" },
  "eligible DReps": { es: "DReps elegibles", zh: "符合条件的 DRep", ja: "対象となる DRep", de: "berechtigte DReps", ru: "подходящие DRep", it: "DRep idonei", fr: "DReps éligibles", pt: "DReps elegíveis", ko: "자격이 있는 DRep", ar: "DReps المؤهلون", hi: "योग्य DReps" },
  "end must be after start.": { es: "el fin debe ser posterior al inicio.", zh: "结束时间必须晚于开始时间。", ja: "終了は開始より後でなければなりません。", de: "Das Ende muss nach dem Beginn liegen.", ru: "конец должен быть позже начала.", it: "la fine deve essere successiva all'inizio.", fr: "la fin doit être postérieure au début.", pt: "o fim deve ser posterior ao início.", ko: "종료는 시작 이후여야 합니다.", ar: "يجب أن تكون النهاية بعد البداية.", hi: "समाप्ति प्रारंभ के बाद होनी चाहिए।" },
