  "auto-start": { es: "inicio automático", zh: "自动开始", ja: "自動開始", de: "Auto-Start", ru: "автозапуск", it: "avvio automatico", fr: "démarrage auto", pt: "início automático", ko: "자동 시작", ar: "بدء تلقائي", hi: "स्वतः-प्रारंभ" },
