  "in progress": { es: "en curso", zh: "进行中", ja: "進行中", de: "in Bearbeitung", ru: "в процессе", it: "in corso", fr: "en cours", pt: "em andamento", ko: "진행 중", ar: "قيد التنفيذ", hi: "प्रगति में" },
  "Passed": { es: "Aprobado", zh: "已通过", ja: "可決", de: "Angenommen", ru: "Принято", it: "Approvato", fr: "Adopté", pt: "Aprovado", ko: "통과됨", ar: "تمّت الموافقة", hi: "पारित" },
